\documentclass{article}
\title{Case Report: Eosinophilic Esophagitis in a 34-Year-Old Runner}
\author{M. Okafor and L. Sandoval}
\date{March 2026}
\begin{document}
\maketitle
\section{Presentation}
A 34-year-old recreational runner presented with six months of intermittent dysphagia.
Physical examination and routine blood work were unremarkable.
There was no history of food impaction or weight loss.
\section{Findings}
Upper endoscopy revealed linear furrows and white exudates throughout the esophagus.
Biopsy confirmed dense eosinophilic infiltration of the squamous epithelium.
\begin{table}[h]
\centering
\caption{Laboratory values on admission}
\label{tab:labs}
\begin{tabular}{lcc}
\toprule
Analyte & Value & Reference range \\
\midrule
Hemoglobin (g/dL) & 14.2 & 13.0--17.0 \\
Eosinophils (\%) & 7.1 & 0.5--5.0 \\
Total IgE (kU/L) & 412 & $<$ 100 \\
\bottomrule
\end{tabular}
\end{table}
\section{Course}
The patient was started on a proton-pump inhibitor and a topical corticosteroid.
Symptoms resolved within eight weeks, and follow-up endoscopy was normal.
\end{document}

